# Calculate indirect effects from the fitted Mplus mediation models
#
# This script reads the Mplus output files generated by the longitudinal
# mediation models, extracts the relevant coefficients, and computes indirect
# effects using the `misty::indirect()` helper.

# Load required packages.
library(misty)
library(MplusAutomation)

# Read the Mplus output objects for the model specifications under investigation.
# The specific model numbering follows the original analysis workflow.
H1 <- readModels("mediation_RDSEM_H1_intervall.out")
H2 <- readModels("mediation_RDSEM_H2_intervall.out")
H3 <- readModels("mediation_RDSEM_H3_intervall.out")
H4 <- readModels("mediation_RDSEM_H4_intervall.out")

# Extract the relevant parameter estimates from the unstandardized output table.
# The selected row index corresponds to the mediation path used in the study.
H1_out <- H1$parameters$unstandardized
H1_est <- H1_out[8, 3]
H1_std <- H1_out[8, 4]
H1ste <- H1_std / sqrt(213)

H2_out <- H2$parameters$unstandardized
H2_est <- H2_out[8, 3]
H2_std <- H2_out[8, 4]
H2ste <- H2_std / sqrt(213)

H3_out <- H3$parameters$unstandardized
H3_est <- H3_out[8, 3]
H3_std <- H3_out[8, 4]
H3ste <- H3_std / sqrt(213)

H4_out <- H4$parameters$unstandardized
H4_est <- H4_out[8, 3]
H4_std <- H4_out[8, 4]
H4ste <- H4_std / sqrt(213)

# Calculate the indirect effect for each model and write the output to a text
# file so the result can be inspected or reported in a reproducible way.
H1 <- indirect(H1_est, H4_est, H1ste, H4ste, write = "H1_indirect.txt")
H2 <- indirect(H2_est, H4_est, H2ste, H4ste, write = "H2_indirect.txt")
H3 <- indirect(H3_est, H4_est, H3ste, H4ste, write = "H3_indirect.txt")
